from __future__ import annotations

import csv
import hashlib
import json
import subprocess
import sys
from pathlib import Path

sys.stdout.reconfigure(encoding="utf-8")

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "docs/audit/dashboard-2026-10-30"
COHORT = OUT / "frontend-residual-pending-shared-and-other-tests.json"
PROGRESS = OUT / "frontend-shared-other-tests-manual-review-progress.json"
rows = json.loads(COHORT.read_text(encoding="utf-8"))["files"]


def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def full_index():
    result = {}
    command = subprocess.run(["rg", "-l", '"review_scope": "full"', str(OUT), "-g", "*.json"],
                             capture_output=True, text=True, check=False)
    assert command.returncode in (0, 1), command.stderr

    def visit(value, ledger):
        if isinstance(value, dict):
            if value.get("review_scope") == "full" and isinstance(value.get("path"), str) and isinstance(value.get("sha256"), str):
                relative = value["path"].replace("\\", "/").removeprefix("./")
                result.setdefault((relative, value["sha256"]), []).append(ledger)
            for item in value.values():
                if isinstance(item, (dict, list)):
                    visit(item, ledger)
        elif isinstance(value, list):
            for item in value:
                visit(item, ledger)

    for name in command.stdout.splitlines():
        path = Path(name)
        if path == PROGRESS:
            continue
        visit(json.loads(path.read_text(encoding="utf-8-sig")), path.name)
    with (OUT / "file-inventory.csv").open(encoding="utf-8-sig") as stream:
        for row in csv.DictReader(stream):
            if row.get("review_scope") == "full":
                result.setdefault((row["path"], row["sha256"]), []).append("file-inventory.csv")
    return result


progress = json.loads(PROGRESS.read_text(encoding="utf-8")) if PROGRESS.exists() else {
    "cohort": COHORT.name, "cohort_sha256": digest(COHORT), "reviewer": "document_ui_architecture",
    "read_only": True, "files": [], "findings": [],
    "method": "Only physically displayed, read and acknowledged source ranges count; metadata triage and prior passing tests do not count. Current exact-hash explicit-full ledgers checked before each new read. No runtime/test/config edits or checks."}
mode = sys.argv[1]
if mode == "ack":
    request = json.loads(sys.argv[2])
    for item in request:
        number = item["id"]
        row = rows[number]
        path = ROOT / row["path"]
        current = digest(path)
        actual_lines = len(path.read_text(encoding="utf-8").splitlines())
        old = next((entry for entry in progress["files"] if entry["path"] == row["path"]), None)
        if old:
            assert old["sha256"] == current
        else:
            old = {"id": number, "path": row["path"], "sha256": current,
                   "physical_lines": actual_lines, "read_line_ranges": [], "notes": []}
            progress["files"].append(old)
        old["read_line_ranges"].append(item.get("range", [1, actual_lines]))
        old["notes"].append(item["notes"])
        covered = {line for start, end in old["read_line_ranges"] for line in range(start, min(end, actual_lines) + 1)}
        old["review_scope"] = "full" if len(covered) == actual_lines else "partial"
        old["status"] = "reviewed" if old["review_scope"] == "full" else "in_progress"
    progress["full_files"] = sum(item["review_scope"] == "full" for item in progress["files"])
    progress["full_physical_lines"] = sum(item["physical_lines"] for item in progress["files"] if item["review_scope"] == "full")
    PROGRESS.write_text(json.dumps(progress, indent=2) + "\n", encoding="utf-8", newline="\n")
    print(json.dumps({"full_files": progress["full_files"], "full_physical_lines": progress["full_physical_lines"]}))
else:
    index = full_index()
    if mode == "index":
        print(json.dumps([{"id": number, "path": row["path"], "lines": len((ROOT / row["path"]).read_text(encoding="utf-8").splitlines()),
                           "current_full_ledgers": index.get((row["path"], digest(ROOT / row["path"])), [])}
                          for number, row in enumerate(rows)], indent=2))
    elif mode == "unicode":
        for number in range(int(sys.argv[2]), int(sys.argv[3]) + 1):
            row = rows[number]
            for line, content in enumerate((ROOT / row["path"]).read_text(encoding="utf-8").splitlines(), 1):
                if any(ord(character) > 127 for character in content):
                    print(json.dumps({"id": number, "path": row["path"], "line": line, "exact_unicode_source": content}, ensure_ascii=True))
    elif mode == "read":
        for argument in sys.argv[2:]:
            parts = argument.split(":")
            number = int(parts[0])
            row = rows[number]
            path = ROOT / row["path"]
            current = digest(path)
            ledgers = index.get((row["path"], current), [])
            prior = next((item for item in progress["files"] if item["path"] == row["path"] and item["sha256"] == current), None)
            if ledgers or prior and prior["review_scope"] == "full":
                print(json.dumps({"id": number, "path": row["path"], "SKIPPED_existing_current_full": ledgers or [PROGRESS.name]}))
                continue
            lines = path.read_text(encoding="utf-8").splitlines()
            start = int(parts[1]) if len(parts) > 1 else 1
            end = min(int(parts[2]), len(lines)) if len(parts) > 2 else len(lines)
            print(json.dumps({"id": number, "path": row["path"], "sha256": current,
                              "physical_lines": len(lines), "displayed_range": [start, end], "matching_full_ledgers": []}))
            for line in range(start, end + 1):
                print(f"{line:4} {lines[line - 1]}")
